<?php require_once "../db.php";require_role("Admin");$id=(int)($_GET['id']??0);$st=$conn->prepare("SELECT h.*,s.name student_name,s.email,s.course,s.semester,q.title quiz_title,q.subject,q.duration,t.name teacher_name FROM quiz_history h JOIN student s ON s.id=h.student_id JOIN quiz q ON q.id=h.quiz_id LEFT JOIN teacher t ON t.id=q.created_by WHERE h.id=?");$st->bind_param("i",$id);$st->execute();$d=$st->get_result()->fetch_assoc();if(!$d){http_response_code(404);die('Quiz attempt not found. <a href="quiz_history.php">Back to history</a>');}$pct=$d['total_questions']?round($d['score']/$d['total_questions']*100,1):0;?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quiz Attempt Detail</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/admin_sidebar.php";?></div><main class="col-lg-10"><div class="py-4 px-lg-3"><a href="quiz_history.php" class="btn btn-sm btn-outline-secondary mb-3">← All quiz history</a><h2 class="fw-bold">Quiz Attempt Details</h2><div class="card panel-card mt-3"><div class="card-body p-4"><h4><?=e($d['quiz_title'])?></h4><p class="text-muted"><?=e($d['subject'])?> · Teacher: <?=e($d['teacher_name']?:'—')?> · Duration: <?=$d['duration']?> min</p><hr><div class="row g-3"><div class="col-md-6"><div class="stat-card p-3 h-100"><small class="text-muted">Student</small><h5 class="mt-1"><a href="student_history.php?id=<?=$d['student_id']?>"><?=e($d['student_name'])?></a></h5><div><?=e($d['email'])?></div><div><?=e($d['course'])?> · <?=e($d['semester'])?></div></div></div><div class="col-md-6"><div class="stat-card p-3 h-100"><small class="text-muted">Score</small><h2 class="fw-bold"><?=$d['score']?> / <?=$d['total_questions']?></h2><div><?=$pct?>%</div></div></div><div class="col-md-3"><div class="stat-card p-3"><b><?=$d['attempted_questions']?></b><br>Attempted</div></div><div class="col-md-3"><div class="stat-card p-3"><b class="text-success"><?=$d['correct_answers']?></b><br>Correct</div></div><div class="col-md-3"><div class="stat-card p-3"><b class="text-danger"><?=$d['wrong_answers']?></b><br>Wrong</div></div><div class="col-md-3"><div class="stat-card p-3"><b><?=e($d['created_at'])?></b><br>Date</div></div></div></div></div></div></main></div></div><script src="../assets/card-links.js"></script></body></html>
